function managementMarkdown(report){const lines=['# Orchestrator management report','',`Period: ${report.since} → ${report.generated_at}`,'',`- ${report.summary.projects} active projects · ${report.summary.average_progress}% average recorded progress`,`- ${report.summary.open_blockers} open blockers across ${report.summary.blocked_projects} projects`,`- ${report.summary.commits} observed commits · ${report.summary.push_attempts} push attempts · ${report.summary.pushes_verified} verified pushes`,`- ${report.summary.trusted_evidence}/${report.summary.evidence} evidence records available and hashed`,`- Recorded cost: $${report.summary.cost.toFixed(2)}`,'','## Projects',''];for(const row of report.projects)lines.push(`### ${row.name}`,'',`- Progress: ${row.progress}% (${row.completed}/${row.objectives})`,`- Blockers: ${row.blocked}${row.oldest_blocker_days?` · oldest ${row.oldest_blocker_days} days`:''}`,`- Git: ${row.git?`${row.git.branch} · ${String(row.git.head_commit||'').slice(0,12)} · ${row.git.dirty?'dirty':'clean'}`:'not reported'}`,`- Activity: ${row.commits} commits · ${row.push_attempts} push attempts · ${row.pushes_verified} verified pushes`,`- Evidence: ${row.trusted_evidence}/${row.evidence} trusted`,'');lines.push('## Open blockers','',...(report.blockers.length?report.blockers.map(row=>`- **${row.project_name}** · ${row.title} · ${row.age_days} days`):['- None']),'','## Provenance','','Push attempts are not counted as successful pushes. A successful push requires an explicit remote/provider verification event. Metrics describe recorded flow and evidence, not individual productivity.','');return lines.join('\n')}
