function projectSchedule(projectSlug,since=null){const db=base(),project=projectBy(projectSlug);if(!project)return{estimated_minutes:0,observed_minutes:0,variance_minutes:0,scheduled:0,overdue:0};const objectives=db.prepare("SELECT id,status,due_at,estimate_minutes FROM objectives WHERE project_id=? AND status!='abandoned'").all(project.id),events=db.prepare("SELECT objective_id,kind,payload,occurred_at FROM events WHERE project_id=? AND kind IN ('work.started','work.finished') AND (? IS NULL OR occurred_at>=?) ORDER BY occurred_at,id").all(project.id,since,since).map(row=>({...row,payload:json.read(row.payload,{})})),starts=new Map(),elapsed=new Map();for(const event of events){const session=event.payload.session_id;if(!session)continue;if(event.kind==='work.started')starts.set(session,event);else{const start=starts.get(session);if(start){const minutes=Math.max(0,(new Date(event.occurred_at).getTime()-new Date(start.occurred_at).getTime())/60000),objectiveId=event.objective_id||start.objective_id;elapsed.set(objectiveId,(elapsed.get(objectiveId)||0)+minutes)}}}const estimated=objectives.reduce((sum,row)=>sum+Number(row.estimate_minutes||0),0),observed=[...elapsed.values()].reduce((sum,value)=>sum+value,0),now=Date.now();return{estimated_minutes:estimated,observed_minutes:Math.round(observed),variance_minutes:Math.round(observed-estimated),scheduled:objectives.filter(row=>row.due_at||row.estimate_minutes!=null).length,overdue:objectives.filter(row=>row.due_at&&row.status!=='proven'&&new Date(row.due_at).getTime()<now).length,next_due:objectives.filter(row=>row.due_at&&row.status!=='proven').sort((a,b)=>String(a.due_at).localeCompare(String(b.due_at)))[0]?.due_at||null}}
