function compareManagementReports(beforeUid=null,afterUid=null){const db=base(),rows=db.prepare('SELECT uid,report_json,generated_at FROM management_reports ORDER BY generated_at DESC LIMIT 100').all(),afterRow=afterUid?rows.find(row=>row.uid===afterUid):rows[0],beforeRow=beforeUid?rows.find(row=>row.uid===beforeUid):rows.find(row=>row.uid!==afterRow?.uid);if(!beforeRow||!afterRow)throw new Error('Two management reports are required for comparison.');const before=json.read(beforeRow.report_json,{}),after=json.read(afterRow.report_json,{}),metrics=['average_progress','open_blockers','commits','pushes_verified','trusted_evidence','cost'],delta=Object.fromEntries(metrics.map(key=>[key,Number(after.summary?.[key]||0)-Number(before.summary?.[key]||0)])),beforeProjects=new Map((before.projects||[]).map(row=>[row.slug,row])),projects=(after.projects||[]).map(row=>{const previous=beforeProjects.get(row.slug)||{};return{slug:row.slug,name:row.name,progress:Number(row.progress||0)-Number(previous.progress||0),blockers:Number(row.blocked||0)-Number(previous.blocked||0),evidence:Number(row.trusted_evidence||0)-Number(previous.trusted_evidence||0),commits:Number(row.commits||0)-Number(previous.commits||0)}});return{format:'orchestrator-management-comparison',version:1,before:{uid:beforeRow.uid,generated_at:beforeRow.generated_at},after:{uid:afterRow.uid,generated_at:afterRow.generated_at},delta,projects,execution:false}}
